SET threads TO 1;
ATTACH 'test.db' (ROW_GROUP_SIZE 8192);
USE test;
CREATE TABLE ssb_flat(
    lo_orderkey        BIGINT,
    lo_linenumber      BIGINT,
    lo_custkey         BIGINT,
    lo_partkey         BIGINT,
    lo_suppkey         BIGINT,
    lo_orderdate       DATE,
    lo_orderpriority   VARCHAR,
    lo_shippriority    BIGINT,
    lo_quantity        BIGINT,
    lo_extendedprice   BIGINT,
    lo_ordertotalprice BIGINT,
    lo_discount        BIGINT,
    lo_revenue         BIGINT,
    lo_supplycost      BIGINT,
    lo_tax             BIGINT,
    lo_commitdate      DATE,
    lo_shipmode        VARCHAR,
    c_custkey          BIGINT,
    c_name             VARCHAR,
    c_address          VARCHAR,
    c_city             VARCHAR,
    c_nation           VARCHAR,
    c_region           VARCHAR,
    c_phone            VARCHAR,
    c_mktsegment       VARCHAR,
    s_suppkey          BIGINT,
    s_name             VARCHAR,
    s_address          VARCHAR,
    s_city             VARCHAR,
    s_nation           VARCHAR,
    s_region           VARCHAR,
    s_phone            VARCHAR,
    p_partkey          BIGINT,
    p_name             VARCHAR,
    p_mfgr             VARCHAR,
    p_category         VARCHAR,
    p_brand            VARCHAR,
    p_color            VARCHAR,
    p_type             VARCHAR,
    p_size             BIGINT,
    p_container        VARCHAR,
    d_datekey          BIGINT,
    d_date             VARCHAR,
    d_dayofweek        VARCHAR,
    d_month            VARCHAR,
    d_year             BIGINT,
    d_yearmonthnum     BIGINT,
    d_yearmonth        VARCHAR,
    d_daynuminweek     BIGINT,
    d_daynuminmonth    BIGINT,
    d_daynuminyear     BIGINT,
    d_monthnuminyear   BIGINT,
    d_weeknuminyear    BIGINT,
    d_sellingseason    VARCHAR,
    d_lastdayinweekfl  BIGINT,
    d_lastdayinmonthfl BIGINT,
    d_holidayfl        BIGINT,
    d_weekdayfl        BIGINT
);;

